/// First frame on every connection.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Hello {
    pub protocol_version: u32,
    pub client: ClientInfo,
    /// Client feature bitmask; the session uses the intersection with the server's
    pub features: u64,
    pub locale: String,
    pub bandwidth_mode: BandwidthMode,
    /// Saves a round trip: authenticate inside HELLO
    pub access_token: Option<String>,
    pub device_id: Option<Id>,
    pub resume: Option<ResumeRequest>,
}

impl Encode for Hello {
    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.enter()?;
        w.write_u32(self.protocol_version);
        self.client.encode(w)?;
        w.write_u64(self.features);
        w.write_str(&self.locale)?;
        w.write_u32(self.bandwidth_mode.to_wire());
        let present = usize::from(self.access_token.is_some())
            + usize::from(self.device_id.is_some())
            + usize::from(self.resume.is_some());
        w.write_u32(present as u32);
        if let Some(v) = &self.access_token {
            w.optional(1, |w| {
                w.write_str(v)?;
                Ok(())
            })?;
        }
        if let Some(v) = &self.device_id {
            w.optional(2, |w| {
                w.write_id(v);
                Ok(())
            })?;
        }
        if let Some(v) = &self.resume {
            w.optional(3, |w| {
                v.encode(w)?;
                Ok(())
            })?;
        }
        w.leave();
        Ok(())
    }
}

impl Decode for Hello {
    fn decode(r: &mut Reader) -> Result<Self> {
        r.enter()?;
        let mut out = Self::default();
        out.protocol_version = r.read_u32()?;
        out.client = ClientInfo::decode(r)?;
        out.features = r.read_u64()?;
        out.locale = r.read_string()?;
        out.bandwidth_mode = BandwidthMode::from_wire(r.read_u32()?);
        let optional_count = r.read_u32()?;
        for _ in 0..optional_count {
            let (field_id, mut owned) = r.read_optional()?;
            let sub = &mut owned;
            match field_id {
                1 => out.access_token = Some(sub.read_string()?),
                2 => out.device_id = Some(sub.read_id()?),
                3 => out.resume = Some(ResumeRequest::decode(sub)?),
                _ => { /* unknown optional field: skipped by length (forward compatibility) */ }
            }
        }
        r.leave();
        Ok(out)
    }
}

