/// Delivery class, deciding what happens when a session queue is full (ADR-0008).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DeliveryClass {
    /// Never dropped. Lagging session is closed with RESUME_REQUIRED instead
    Critical,
    /// Newest replaces oldest for the same coalescing key
    Coalescable,
    /// Dropped silently under pressure, counted in metrics
    Droppable,
}

/// Minimum session state an opcode requires.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum AuthLevel {
    /// Allowed on an unauthenticated session
    None,
    /// Requires an authenticated user session
    User,
    /// Requires a bot session with the matching capability
    Bot,
    /// Mesh-internal only. Never accepted from a client socket
    Server,
}

/// Direction an opcode may legally travel.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Direction {
    ClientToServer,
    ServerToClient,
    Both,
}

